#include <iostream>
#include <vector>
#include <memory>
#include <utility>

#include "SpreadSheetCell.h"
#include "DoubleSpreadsheet.cpp"

//#include "StringSpreadsheet.cpp"

using namespace std;


int main(){

    vector<unique_ptr<SpreadSheetCell>> Excel ;


  unique_ptr<SpreadSheetCell> cell = make_unique<DoubleSpreadsheet>();


    cell->set("34.5");

    Excel.push_back(std::move(cell)); //move(cell)


    for(const unique_ptr<SpreadSheetCell> & cell : Excel){
        cout<<cell->getString();
    }


    return 0;
}

#include "SpreadSheetCell.h"
#include <optional>
#include <string>
#include <string_view>

using namespace std;



class DoubleSpreadsheet : public SpreadSheetCell
{
    private:

    optional<double> data;

    public:
     DoubleSpreadsheet( ){
        data = 0;
    }

    DoubleSpreadsheet(string_view value){

        data = stringToDouble(value);
    }

    void set(std::string_view value) override{
        data = stringToDouble(value);
    }

    std::string getString() const override{

        return doubleToString(data.value_or(0.0));
    }
    string doubleToString(double value)const
    {

       return to_string(value);
    }
    double stringToDouble(std::string_view value) const
    {
        return stod(string(value));
    }

};

